<?php

declare(strict_types=1);

namespace TheBeardedBear\UrssafTiersPrestations\Domain\Customer;

use TheBeardedBear\UrssafTiersPrestations\Domain\Exception\RecordNotFound;
use TheBeardedBear\UrssafTiersPrestations\Domain\Shared\ExternalReference;
use TheBeardedBear\UrssafTiersPrestations\Domain\Shared\Instant;
use TheBeardedBear\UrssafTiersPrestations\Domain\Shared\TenantId;
use TheBeardedBear\UrssafTiersPrestations\Domain\Shared\UrssafCustomerId;

/**
 * Persistence port of {@see CustomerRegistration}. Identities are generated by the application (IdGenerator port).
 *
 * Uniqueness expected from implementations: the id; (tenant, external reference); (tenant, URSSAF customer id) when set.
 * Lists are ordered by last update, oldest first (so that polling visits every registration in turn).
 */
interface CustomerRegistrationRepository
{
    /**
     * Inserts or updates the registration. Domain events are not persisted: release and publish them separately.
     */
    public function save(CustomerRegistration $registration): void;

    /**
     * @throws RecordNotFound "customer_registration.not_found"
     */
    public function get(RegistrationId $id): CustomerRegistration;

    public function findByExternalReference(TenantId $tenantId, ExternalReference $externalReference): ?CustomerRegistration;

    public function findByUrssafCustomerId(TenantId $tenantId, UrssafCustomerId $urssafCustomerId): ?CustomerRegistration;

    /**
     * Registrations of the tenant whose pairing status must be polled with method 020: states awaiting_pairing,
     * blocked and mandate_expired ({@see RegistrationState::hasPairingToFollow()}), least recently updated first.
     *
     * @param positive-int $limit
     *
     * @return list<CustomerRegistration>
     */
    public function findPairingToFollow(TenantId $tenantId, int $limit): array;

    /**
     * Registrations of every tenant in state submitting whose last attempt started at or before olderThan (i.e.
     * {@see CustomerRegistration::isStaleSubmission()} with olderThan = now - staleAfter), oldest attempt first.
     *
     * @param positive-int $limit
     *
     * @return list<CustomerRegistration>
     */
    public function findStaleSubmissions(Instant $olderThan, int $limit): array;

    /**
     * @param positive-int $limit
     *
     * @return list<CustomerRegistration>
     */
    public function findByState(TenantId $tenantId, RegistrationState $state, int $limit): array;

    /**
     * Distinct tenants having at least one registration whose pairing status must be polled (see
     * {@see self::findPairingToFollow()}), the tenant of the least recently updated one first.
     *
     * @return list<TenantId>
     */
    public function tenantsWithPairingToFollow(): array;

    /**
     * Removes the registration (GDPR erasure); nothing happens when it does not exist. Domain events are not
     * recorded: anonymise() it instead to keep the history without the personal data.
     */
    public function delete(RegistrationId $id): void;

    /**
     * Atomically moves the registration from pending to submitting (compare-and-set on the stored state, e.g.
     * "UPDATE ... SET state = 'submitting', updated_at = :now, last_attempt_at = :now, attempts = attempts + 1
     * WHERE id = :id AND state = 'pending'"), exactly like {@see CustomerRegistration::startSubmission()}, so that a
     * single worker submits it.
     *
     * Returns true when this call won the claim; false when the registration does not exist or is not pending.
     * No domain event is recorded: the winner loads the registration with {@see self::get()} (now in state
     * submitting) and continues with markSubmitted() / markRejected() / markFailed() / markInvalidCredentials().
     */
    public function claimForSubmission(RegistrationId $id, Instant $now): bool;
}
